<template><section class="admin-workspace"><div class="catalog-heading"><div><p class="eyebrow">退款与退货</p><h1>售后处理</h1></div><button class="icon-button" title="刷新" aria-label="刷新" @click="load">↻</button></div><form class="admin-filter" @submit.prevent="load"><select v-model="status"><option value="">全部状态</option><option value="PENDING_REVIEW">待审核</option><option value="WAITING_RETURN">等待寄回</option><option value="WAITING_RECEIPT">等待收货</option><option value="COMPLETED">已完成</option><option value="REJECTED">已拒绝</option></select><select v-model="type"><option value="">全部类型</option><option value="REFUND">退款</option><option value="RETURN">退货</option></select><button class="secondary-button">筛选</button></form><PageStatus :loading="loading" :error="error" :empty="!result?.items.length" empty-text="暂无售后申请" @retry="load"/><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>申请单</th><th>关联订单</th><th>类型 / 状态</th><th>原因</th><th>金额</th><th>操作</th></tr></thead><tbody><tr v-for="item in result?.items" :key="item.id"><td>{{ item.requestNo }}</td><td>{{ item.orderNo }}</td><td>{{ item.type === 'REFUND' ? '退款' : '退货' }} / {{ states[item.status] }}</td><td>{{ item.reason }}</td><td>¥{{ price(item.requestedAmount) }}</td><td><button class="text-action" @click="selected=item">处理</button></td></tr></tbody></table></div><PagePagination v-if="result" :total="result.total" :page="result.page" :busy="loading" @change="changePage"/>
  <section v-if="selected" class="order-detail-panel"><div class="catalog-heading"><div><p class="eyebrow">{{ selected.requestNo }}</p><h2>{{ selected.type === 'REFUND' ? '退款申请' : '退货申请' }}</h2></div><button class="icon-button" title="关闭" aria-label="关闭" @click="selected=null">×</button></div><p>订单 {{ selected.orderNo }} · {{ selected.reason }}</p><p>{{ selected.description }}</p><div v-for="item in selected.items" :key="item.orderItemId" class="checkout-line"><span>{{ item.productName }} · {{ item.specification }} · {{ item.requestedQuantity }} 件 · ¥{{ price(item.unitPrice) }}</span></div><p v-if="selected.returnTrackingNumber">寄回物流：{{ selected.returnCarrier }} · {{ selected.returnTrackingNumber }}</p><template v-if="selected.status==='PENDING_REVIEW'"><label class="form-field">审核原因<input v-model="reason" required maxlength="500"></label><div class="order-actions"><button class="primary-button" :disabled="busy || !reason.trim()" @click="review(true)">批准</button><button class="secondary-button" :disabled="busy || !reason.trim()" @click="review(false)">拒绝</button></div></template><template v-if="selected.status==='WAITING_RECEIPT'"><h3>确认退货收货</h3><div v-for="item in selected.items" :key="item.orderItemId" class="return-receive-row"><strong>{{ item.productName }} · 申请 {{ item.requestedQuantity }}</strong><label>退款数量<input v-model.number="received[item.orderItemId].refundQuantity" type="number" min="0" :max="item.requestedQuantity"></label><label>可入库数量<input v-model.number="received[item.orderItemId].restockQuantity" type="number" min="0" :max="item.requestedQuantity"></label></div><button class="primary-button" :disabled="busy" @click="receive">确认收货并退款</button></template><p v-if="actionError" class="form-message-error">{{ actionError }}</p><p v-if="notice" class="form-message-success">{{ notice }}</p></section>
</section></template>
<script setup lang="ts">
import { ref, watch } from 'vue'; import PageStatus from '../components/PageStatus.vue'; import PagePagination from '../components/PagePagination.vue'; import { errorMessage, price } from '../api/catalog'; import { listAdminAfterSales, receiveAfterSale, reviewAfterSale, type AfterSale, type Page } from '../api/orders'
const states:Record<string,string>={PENDING_REVIEW:'待审核',WAITING_RETURN:'等待寄回',WAITING_RECEIPT:'等待收货',COMPLETED:'已完成',REJECTED:'已拒绝'}
const result=ref<Page<AfterSale>|null>(null),selected=ref<AfterSale|null>(null),loading=ref(false),busy=ref(false),error=ref(''),actionError=ref(''),notice=ref(''),status=ref(''),type=ref(''),reason=ref(''),page=ref(1),received=ref<Record<number,{refundQuantity:number;restockQuantity:number}>>({})
async function load(){loading.value=true;error.value='';try{result.value=await listAdminAfterSales({status:status.value||undefined,type:type.value||undefined,page:page.value,size:12})}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}
function changePage(p:number){page.value=p;void load()}
watch(selected,v=>{reason.value='';actionError.value='';notice.value='';received.value=Object.fromEntries((v?.items??[]).map(i=>[i.orderItemId,{refundQuantity:i.requestedQuantity,restockQuantity:i.requestedQuantity}]))})
async function review(approved:boolean){if(!selected.value)return;busy.value=true;actionError.value='';try{selected.value=await reviewAfterSale(selected.value.id,approved,reason.value.trim());notice.value=approved?'审核已通过':'申请已拒绝';await load()}catch(e){actionError.value=errorMessage(e)}finally{busy.value=false}}
async function receive(){if(!selected.value)return;busy.value=true;actionError.value='';try{selected.value=await receiveAfterSale(selected.value.id,selected.value.items.map(i=>({orderItemId:i.orderItemId,...received.value[i.orderItemId]})));notice.value='已登记收货、退款与入库数量';await load()}catch(e){actionError.value=errorMessage(e)}finally{busy.value=false}}
void load()
</script>
